package com.exepex.stratum.cache;
public class StratumCache {
  public Object get(Object key, java.util.function.Supplier<Object> loader) {
    try {
      return loader.get();
    } catch (RuntimeException e) {
      return afterFailedWrite(key);
    }
  }
  private Object afterFailedWrite(Object key) {
    try {
      return key.toString();
    } catch (RuntimeException e) {
      throw new IllegalStateException(e);
    }
  }
}

package com.exepex.stratum.cache;
public class StratumCache {
  public void put(Object key, java.util.function.Supplier<Object> value) {
    try {
      value.get();
    } catch (RuntimeException e) {
      return;
    }
  }
}

